def most_frequent_char(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    best = None
    best_count = 0
    for ch in sorted(counts):
        if counts[ch] > best_count:
            best = ch
            best_count = counts[ch]
    return best


print(most_frequent_char(s))

