def title_case(s):
    small = {"a", "an", "the", "and", "or", "of", "in", "on", "at", "to"}
    words = s.split()
    out = []
    for i, w in enumerate(words):
        if i > 0 and w in small:
            out.append(w)
        else:
            out.append(w[0].upper() + w[1:])
    return " ".join(out)


print(title_case(s))
